67	/**
68	 * Read-only Plate editor that renders a markdown plan and lets the reviewer
69	 * drop anchored Comment / Deletion / Insertion / Replacement marks via a
70	 * floating selection toolbar. The editor stays `readOnly={true}`; marks are
71	 * applied programmatically through {@link applyAnnotation} via `editor.tf.*`
72	 * transforms, which bypass `contenteditable=false`.
73	 *
74	 * Insertion authoring shares the Comment composer's UX —
75	 * {@link AnnotationComposer} switches accent + labels based on `kind`.
76	 */
77	export const ReviewEditor = ({
78	  markdown,
79	  initialValue,
80	  initialBodies,
81	  initialImages,
82	  initialCommentOriginalTexts,
83	  initialSuggestionOriginalTexts,
84	  initialInsertionNewTexts,
85	  initialInsertionImages,
86	  initialInsertionOriginalTexts,
87	  initialReplacementTexts,
88	  initialReplacementImages,
89	  initialReplacementOriginalTexts,
90	  onReady,
91	  onChange,
92	  onComposerOpenChange,
93	}: ReviewEditorProps): React.ReactElement => {
94	  const containerRef = useRef<HTMLDivElement | null>(null);
95	  const { maps, setters } = useAnnotationState({
96	    initialBodies,
97	    initialImages,
98	    initialCommentOriginalTexts,
99	    initialSuggestionOriginalTexts,
100	    initialInsertionNewTexts,
101	    initialInsertionImages,
102	    initialInsertionOriginalTexts,
103	    initialReplacementTexts,
104	    initialReplacementImages,
105	    initialReplacementOriginalTexts,
106	  });
107	
108	  const editor = usePlateEditor({
109	    plugins: SymbiotEditorKit,
110	    value: (e): never => {
111	      if (initialValue !== undefined) return initialValue as never;
112	      const deserialized = e.getApi(MarkdownPlugin).markdown.deserialize(markdown);
113	      return stampBlockLines(markdown, deserialized) as never;
114	    },
115	  });
116	
117	  const { pending, setPending, onComposerSave, onComposerCancel } = useComposerController(
118	    editor,
119	    maps,
120	    setters,
121	    onChange
122	  );
123	
124	  useTypingGuard(containerRef);
125	
126	  const onRemoveAnnotation = useRemoveAnnotation(editor, maps, setters, onChange);
127	  const onUpdateAnnotation = useUpdateAnnotation(maps, setters);
128	
129	  useEffect(() => {
130	    onChange?.(snapshotOf(editor, maps));
131	  }, [editor, maps, onChange]);
132	
133	  useEffect(() => {
134	    onComposerOpenChange?.(pending !== null);
135	  }, [pending, onComposerOpenChange]);
136	
137	  const { onCommentClick, onInsertClick, onReplaceClick, onDeleteClick, triggerAnnotation } =
138	    useToolbarHandlers({
139	      editor,
140	      maps,
141	      setters,
142	      setPending,
143	      onChange,
144	    });
145	
146	  useReadyHandle(editor, maps, onRemoveAnnotation, onUpdateAnnotation, triggerAnnotation, onReady);
147	
148	  const onToggleTask = useTaskToggle(editor, maps, onChange);
149	
150	  return (
151	    <div
152	      ref={containerRef}
153	      data-testid="editor-root"
154	      className="prose prose-neutral dark:prose-invert relative mx-auto max-w-3xl"
155	    >
156	      <TaskToggleContext value={onToggleTask}>
157	        <Plate editor={editor}>
158	          <PlateContent readOnly className="outline-none" />
159	          <ToolbarButtons
160	            onComment={onCommentClick}
161	            onInsert={onInsertClick}
162	            onReplace={onReplaceClick}
163	            onDelete={onDeleteClick}
164	          />
165	        </Plate>
166	      </TaskToggleContext>
167	      <AnnotationComposer
168	        kind={pending?.kind ?? "comment"}
169	        open={pending !== null}
170	        quote={pending?.applied.anchorText ?? ""}
171	        onSave={onComposerSave}
172	        onCancel={onComposerCancel}
173	      />
