const recordCancelDiag = (editor: PlateEditor, pending: PendingAuthoring): void => {
  if (typeof document === "undefined") return;
  const w = window as unknown as { __diag?: unknown[] };
  const log = (w.__diag ??= []);
  const editorRoot = document.querySelector('[data-testid="editor-root"]');
  const snapshot = (ev: string): Record<string, unknown> => {
    const active = document.activeElement;
    return {
      ev,
      id: pending.applied.id,
      modelClean: !hasAnnotationMark(editor, pending.kind, pending.applied.id),
      domCount: document.querySelectorAll(`[data-testid="annotation-${pending.kind}"]`).length,
      activeTag: active ? active.tagName : null,
      activeTestId: active ? active.getAttribute("data-testid") : null,
      editorHasFocus: active !== null && editorRoot !== null && editorRoot.contains(active),
    };
  };
  log.push(snapshot("cancel"));
  // Focus-theory probe (symbiot#236): re-snapshot after the dismiss event settles and Radix
  // restores focus, to reveal WHERE focus lands per route (overlay click vs Cancel/Escape).
  setTimeout(() => log.push(snapshot("cancel+tick")), 0);
};

